INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Columbus Council District 8', 'ga', 'columbus-ga-council-district-8', 'X0044', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'columbus-ga-council-district-8' AND mtfcc = 'X0044' AND district_type = 'LOCAL'
