-- --- 2. Government ----------------------------------------------------------
-- ⚠ The charter's corporate name is the bare "Columbus, Georgia" (Sec. 1-100),
-- which is not a usable row label; the government is universally published as
-- the Columbus Consolidated Government.

INSERT INTO essentials.governments (name, type, state, city, geo_id)
SELECT 'Columbus Consolidated Government, Georgia, US', 'City', 'GA', 'Columbus', '1319000'
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.governments WHERE geo_id = '1319000' AND type = 'City'
);

-- --- 3. Chambers ------------------------------------------------------------
-- ⚠ chambers.slug is GENERATED from name_formal and cannot be inserted.
-- Getting name_formal wrong silently yields a different slug.

INSERT INTO essentials.chambers
  (government_id, name, name_formal, official_count, policy_engagement_level)
SELECT g.id, 'Columbus Council', 'Columbus Council', 10, 'full'
FROM essentials.governments g
WHERE g.geo_id = '1319000' AND g.type = 'City'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.chambers c WHERE c.government_id = g.id AND c.name = 'Columbus Council'
  );

