  );

-- --- 4. Offices -------------------------------------------------------------
-- Every title is distinct, so a NOT EXISTS-on-title guard cannot collapse rows.
-- ⚠ The CROSS JOIN LATERAL resolves each district by geo_id + mtfcc +
-- district_type. If it matches nothing the row VANISHES and no office is
-- inserted, with no error -- which is what the pre-flight slug check and the
-- per-district post-verify below exist to catch.

INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers, representation_note)
SELECT c.id, d.id, 'Mayor', 'GA', 'Columbus', 'non_voting', 'The Mayor of Columbus is elected countywide and presides over the ten-member Columbus Council. Under Section 4-201 of the Charter of Columbus, Georgia, the Mayor has a voice in the Council''s proceedings but the right to vote only in the case of a tie, and is deemed a member of the Council for that purpose only. Six of the ten councilors form a quorum, which counts the Mayor out of the body. The Mayor is the official spokesperson and the official head of the consolidated government, and nominates the city manager and the city attorney, each nomination taking effect only when six members of the Council confirm it.'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = '1319000' AND dd.mtfcc = 'G4110'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1319000' AND g.type = 'City' AND c.name = 'Office of the Mayor'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Mayor'
  );
INSERT INTO essentials.offices
